 INSERT INTO `energy_power_arm` (`power_arm_id`,`version_id`,`power_arm_code`,`start_km`,`end_km`,`direction`,`max_traction_supply_kw`,`max_regen_absorption_kw`,`max_grid_feedback_kw`,`direct_use_allowed`,`needs_manual_review`,`data_status`,`source_note`) SELECT s.`power_arm_id`,s.`version_id`,s.`power_arm_code`,s.`start_km`,s.`end_km`,s.`direction`,s.`max_traction_supply_kw`,s.`max_regen_absorption_kw`,s.`max_grid_feedback_kw`,s.`direct_use_allowed`,s.`needs_manual_review`,s.`data_status`,s.`source_note` FROM `seed_energy_power_arm` s WHERE NOT EXISTS(SELECT 1 FROM `energy_power_arm` t WHERE (BINARY t.`power_arm_id` <=> BINARY s.`power_arm_id`) AND (BINARY t.`version_id` <=> BINARY s.`version_id`) AND (BINARY t.`power_arm_code` <=> BINARY s.`power_arm_code`) AND (BINARY t.`start_km` <=> BINARY s.`start_km`) AND (BINARY t.`end_km` <=> BINARY s.`end_km`) AND (BINARY t.`direction` <=> BINARY s.`direction`) AND (BINARY t.`max_traction_supply_kw` <=> BINARY s.`max_traction_supply_kw`) AND (BINARY t.`max_regen_absorption_kw` <=> BINARY s.`max_regen_absorption_kw`) AND (BINARY t.`max_grid_feedback_kw` <=> BINARY s.`max_grid_feedback_kw`) AND (BINARY t.`direct_use_allowed` <=> BINARY s.`direct_use_allowed`) AND (BINARY t.`needs_manual_review` <=> BINARY s.`needs_manual_review`) AND (BINARY t.`data_status` <=> BINARY s.`data_status`) AND (BINARY t.`source_note` <=> BINARY s.`source_note`));
