 INSERT INTO `single_version` (`version_id`,`target_module`,`project_code`,`version_code`,`version_name`,`route_name`,`status`,`data_status`,`files_json`,`parameters_json`,`provenance_json`,`content_sha256`,`created_by`) SELECT s.`version_id`,s.`target_module`,s.`project_code`,s.`version_code`,s.`version_name`,s.`route_name`,s.`status`,s.`data_status`,s.`files_json`,s.`parameters_json`,s.`provenance_json`,s.`content_sha256`,s.`created_by` FROM `seed_single_version` s WHERE NOT EXISTS(SELECT 1 FROM `single_version` t WHERE (BINARY t.`version_id` <=> BINARY s.`version_id`) AND (BINARY t.`target_module` <=> BINARY s.`target_module`) AND (BINARY t.`project_code` <=> BINARY s.`project_code`) AND (BINARY t.`version_code` <=> BINARY s.`version_code`) AND (BINARY t.`version_name` <=> BINARY s.`version_name`) AND (BINARY t.`route_name` <=> BINARY s.`route_name`) AND (BINARY t.`status` <=> BINARY s.`status`) AND (BINARY t.`data_status` <=> BINARY s.`data_status`) AND (BINARY t.`files_json` <=> BINARY s.`files_json`) AND (BINARY t.`parameters_json` <=> BINARY s.`parameters_json`) AND (BINARY t.`provenance_json` <=> BINARY s.`provenance_json`) AND (BINARY t.`content_sha256` <=> BINARY s.`content_sha256`) AND (BINARY t.`created_by` <=> BINARY s.`created_by`));
 INSERT INTO `energy_dept_project` (dept_id,project_code,enabled,create_by,create_time) SELECT target_dept,CONVERT(0x616c676f726974686d5f64656d6f5f32303236313131335f616c6c USING utf8mb4),'1','algorithm_demo_init',NOW() WHERE NOT EXISTS(SELECT 1 FROM `energy_dept_project` WHERE dept_id=target_dept AND project_code=CONVERT(0x616c676f726974686d5f64656d6f5f32303236313131335f616c6c USING utf8mb4));
 INSERT INTO `single_dept_project` (dept_id,project_code,enabled) SELECT target_dept,CONVERT(0x616c676f726974686d5f64656d6f5f32303236313131335f616c6c USING utf8mb4),1 WHERE NOT EXISTS(SELECT 1 FROM `single_dept_project` WHERE dept_id=target_dept AND project_code=CONVERT(0x616c676f726974686d5f64656d6f5f32303236313131335f616c6c USING utf8mb4));
